import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];

  // Design tokens
  const colorBg = new THREE.Color('#0b0b10');
  const colorPaper = new THREE.Color('#e8ecf2');
  const colorAccent = new THREE.Color('#ff2a38');

  const TOTAL_PARTICLES = 1200;
  const CORE_PARTICLES = 90;
  const FIELD_PARTICLES = TOTAL_PARTICLES - CORE_PARTICLES;

  // Generate particle positions
  function generateParticles(count, isCoreRegion) {
    const positions = new Float32Array(count * 3);
    const basePositions = new Float32Array(count * 3);
    const scales = new Float32Array(count);
    const opacities = new Float32Array(count);

    for (let i = 0; i < count; i++) {
      let x, y, z;

      if (isCoreRegion) {
        // Sphere at origin, 0.5 unit radius
        const phi = Math.random() * Math.PI * 2;
        const theta = Math.acos(Math.random() * 2 - 1);
        const r = Math.random() * 0.5;
        x = r * Math.sin(theta) * Math.cos(phi);
        y = r * Math.sin(theta) * Math.sin(phi);
        z = r * Math.cos(theta);
      } else {
        // Ellipsoidal shell 6×4×5 centered at [0,0,-1.5]
        const phi = Math.random() * Math.PI * 2;
        const theta = Math.acos(Math.random() * 2 - 1);
        const r = Math.random();
        x = r * 6 * Math.sin(theta) * Math.cos(phi) / 2;
        y = r * 4 * Math.sin(theta) * Math.sin(phi) / 2;
        z = r * 5 * Math.cos(theta) / 2 - 1.5;
      }

      positions[i * 3] = x;
      positions[i * 3 + 1] = y;
      positions[i * 3 + 2] = z;

      basePositions[i * 3] = x;
      basePositions[i * 3 + 1] = y;
      basePositions[i * 3 + 2] = z;

      scales[i] = 1.0;

      // Depth falloff: z=0 → opacity 0.9, z=-5 → opacity 0.15
      const depthOpacity = isCoreRegion 
        ? 0.9 
        : Math.max(0.15, Math.min(0.9, 0.9 - Math.max(0, -z) / 5 * 0.75));
      opacities[i] = depthOpacity;
    }

    return { positions, basePositions, scales, opacities };
  }

  const fieldData = generateParticles(FIELD_PARTICLES, false);
  const coreData = generateParticles(CORE_PARTICLES, true);

  // Base icosahedron geometry (radius 0.012)
  const baseGeometry = new THREE.IcosahedronGeometry(0.012, 2);

  // Field geometry with attributes
  const fieldGeometry = baseGeometry.clone();
  fieldGeometry.setAttribute('instancePosition', new THREE.InstancedBufferAttribute(fieldData.positions, 3));
  fieldGeometry.setAttribute('basePosition', new THREE.InstancedBufferAttribute(fieldData.basePositions, 3));
  fieldGeometry.setAttribute('instanceScale', new THREE.InstancedBufferAttribute(fieldData.scales, 1));
  fieldGeometry.setAttribute('instanceOpacity', new THREE.InstancedBufferAttribute(fieldData.opacities, 1));

  // Core geometry with attributes
  const coreGeometry = baseGeometry.clone();
  coreGeometry.setAttribute('instancePosition', new THREE.InstancedBufferAttribute(coreData.positions, 3));
  coreGeometry.setAttribute('basePosition', new THREE.InstancedBufferAttribute(coreData.basePositions, 3));
  coreGeometry.setAttribute('instanceScale', new THREE.InstancedBufferAttribute(coreData.scales, 1));
  coreGeometry.setAttribute('instanceOpacity', new THREE.InstancedBufferAttribute(coreData.opacities, 1));

  // Field material: paper color, self-lit 0.9
  const fieldMaterial = new THREE.MeshStandardMaterial({
    color: colorPaper,
    metalness: 0,
    roughness: 1.0,
    emissive: colorPaper,
    emissiveIntensity: 0.9,
    transparent: true,
    toneMapped: false,
  });

  // Core material: accent color, additive, emissive 1.8
  const coreMaterial = new THREE.MeshStandardMaterial({
    color: colorAccent,
    metalness: 0,
    roughness: 0.8,
    emissive: colorAccent,
    emissiveIntensity: 1.8,
    transparent: true,
    blending: THREE.AdditiveBlending,
    toneMapped: false,
  });

  // Instanced meshes
  const fieldMesh = new THREE.InstancedMesh(fieldGeometry, fieldMaterial, FIELD_PARTICLES);
  const coreMesh = new THREE.InstancedMesh(coreGeometry, coreMaterial, CORE_PARTICLES);

  group.add(fieldMesh);
  group.add(coreMesh);

  // Ambient drift: orbit ±0.04 units at 0.05 Hz
  const driftState = { time: 0 };

  const updateDrift = () => {
    const t = driftState.time * 0.001; // Convert to seconds

    // Update field particles
    for (let i = 0; i < FIELD_PARTICLES; i++) {
      const bx = fieldData.basePositions[i * 3];
      const by = fieldData.basePositions[i * 3 + 1];
      const bz = fieldData.basePositions[i * 3 + 2];

      const distFromCore = Math.sqrt(bx * bx + by * by + bz * bz);
      const phase = distFromCore * 0.5; // Phase offset based on distance
      const driftT = t * 0.314 + phase; // 0.05 Hz ≈ 0.314 rad/s

      const dx = Math.cos(driftT) * 0.04;
      const dy = Math.sin(driftT) * 0.04;

      const matrix = new THREE.Matrix4();
      matrix.setPosition(bx + dx, by + dy, bz);
      matrix.scale(new THREE.Vector3(fieldData.scales[i], fieldData.scales[i], fieldData.scales[i]));
      fieldMesh.setMatrixAt(i, matrix);
    }
    fieldMesh.instanceMatrix.needsUpdate = true;

    // Update core particles
    for (let i = 0; i < CORE_PARTICLES; i++) {
      const bx = coreData.basePositions[i * 3];
      const by = coreData.basePositions[i * 3 + 1];
      const bz = coreData.basePositions[i * 3 + 2];

      const distFromCore = Math.sqrt(bx * bx + by * by + bz * bz);
      const phase = distFromCore * 0.5;
      const driftT = t * 0.314 + phase;

      const dx = Math.cos(driftT) * 0.04;
      const dy = Math.sin(driftT) * 0.04;

      const matrix = new THREE.Matrix4();
      matrix.setPosition(bx + dx, by + dy, bz);
      matrix.scale(new THREE.Vector3(coreData.scales[i], coreData.scales[i], coreData.scales[i]));
      coreMesh.setMatrixAt(i, matrix);
    }
    coreMesh.instanceMatrix.needsUpdate = true;
  };

  const driftTimeline = gsap.to(driftState, {
    time: 20000,
    duration: 20000 / 0.314,
    repeat: -1,
    ease: 'none',
    onUpdate: updateDrift,
  });
  timelines.push(driftTimeline);

  // Core pulse: emissive intensity 1.5 to 1.8 sine at 0.1 Hz
  const pulseState = { intensity: 1.8 };
  const pulseTimeline = gsap.to(pulseState, {
    intensity: 1.5,
    duration: 5,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut',
    onUpdate() {
      coreMaterial.emissiveIntensity = pulseState.intensity;
    }
  });
  timelines.push(pulseTimeline);

  // Fog: linear, near 4, far 10, color #0b0b10
  group.fog = new THREE.Fog(colorBg, 4, 10);

  // === TEXT CONTENT ===
  const textMeshes = [];

  if (ctx.fontAtlas) {
    // Hero text: "NOVA ATELIER" at z=0.5, y=0.5 (2x base rhythm)
    const heroMesh = ctx.fontAtlas.renderText({
      text: 'NOVA ATELIER',
      font: 'Lora',
      fontSize: 124,
      fontWeight: 600,
      letterSpacing: -0.01,
      color: colorPaper,
      atlas: 0,
    });
    if (heroMesh) {
      heroMesh.position.set(0, 0.5, 0.5);
      heroMesh.scale.multiplyScalar(0.01);
      group.add(heroMesh);
      textMeshes.push(heroMesh);
    }

    // Subhead: 0.75 units below hero baseline
    const subheadMesh = ctx.fontAtlas.renderText({
      text: 'Precision instruments for the dark hours.',
      font: 'JetBrains Mono',
      fontSize: 40,
      fontWeight: 400,
      letterSpacing: 0.02,
      color: colorPaper,
      atlas: 0,
    });
    if (subheadMesh) {
      subheadMesh.position.set(0, 0.5 - 0.75, 0.5);
      subheadMesh.scale.multiplyScalar(0.01);
      group.add(subheadMesh);
      textMeshes.push(subheadMesh);
    }

    // Caption: 2.25 units below center (on 0.25-unit rhythm)
    const captionMesh = ctx.fontAtlas.renderText({
      text: 'EST. 2019 / GENEVA AND KYOTO',
      font: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 400,
      letterSpacing: 0.08,
      color: colorPaper,
      atlas: 0,
    });
    if (captionMesh) {
      captionMesh.position.set(0, -2.25, 0.5);
      captionMesh.scale.multiplyScalar(0.01);
      group.add(captionMesh);
      textMeshes.push(captionMesh);
    }
  }

  // Apply cinematic primitive: particle-emerge
  if (ctx.primitives && ctx.primitives['particle-emerge']) {
    ctx.primitives['particle-emerge'](group, {
      count: TOTAL_PARTICLES,
      durationMs: 1400,
    });
  }

  // Cleanup
  group.userData.cleanup = () => {
    fieldGeometry.dispose();
    coreGeometry.dispose();
    baseGeometry.dispose();
    fieldMaterial.dispose();
    coreMaterial.dispose();

    textMeshes.forEach(mesh => {
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) mesh.material.dispose();
    });

    timelines.forEach(tl => {
      if (tl.kill) tl.kill();
    });
  };

  return group;
}
